cat > /root/webbot/nav.js <<'EOJS'
// РОЗВІДКА: чи можна пересуватись меню після помилки. ТІЛЬКИ НАВІГАЦІЯ, жодних записів.
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const env = {};
  for (const l of fs.readFileSync('/root/unitex-finrep/secure/odata_write.env','utf8').split('\n')) {
    const m = l.match(/^\s*([A-Z_]+)\s*=\s*(.+?)\s*$/); if (m) env[m[1]] = m[2];
  }
  const browser = await chromium.launch({ args:['--no-sandbox','--ignore-certificate-errors'] });
  const ctx = await browser.newContext({ ignoreHTTPSErrors:true, viewport:{width:1500,height:950}, locale:'uk-UA' });
  const page = await ctx.newPage();
  page.on('dialog', d => d.accept());
  await page.goto('https://unitex.rdport.net:29231/DB/', { waitUntil:'load', timeout:60000 });
  await page.waitForTimeout(7000);
  await page.fill('#userName', env.ODATA_USER);
  await page.fill('#userPassword', env.ODATA_PASS);
  await page.press('#userPassword','Enter');
  await page.waitForTimeout(35000);

  // чи є кнопки помилки і чи є звичайне «ОК/Закрити»
  const btns = await page.evaluate(() => Array.from(document.querySelectorAll('div,span,button'))
      .map(n => (n.innerText||'').trim())
      .filter(t => t && t.length < 30 && /^(ОК|Ok|Закрити|Продовжити|Перезапустити|Завершити|Скасувати)$/i.test(t)));
  console.log('КНОПКИ:', JSON.stringify([...new Set(btns)]));

  // пробуємо відкрити пункт меню «Експедирування» — це лише навігація
  let opened = false;
  for (const name of ['Експедирування','Головне']) {
    const el = await page.$(`text="${name}"`);
    if (el) { await el.click({ timeout: 8000 }).catch(()=>{}); opened = true; await page.waitForTimeout(6000); break; }
  }
  console.log('клік по меню зроблено:', opened);
  const t = await page.evaluate(() => document.body ? document.body.innerText : '');
  console.log('ЕКРАН ПІСЛЯ КЛІКУ:');
  console.log(t.replace(/\n{2,}/g,'\n').slice(0,2000));
  await page.screenshot({ path:'/root/webbot/shots/31-nav.png' });
  await browser.close();
})().catch(e => { console.log('ПОМИЛКА:', String(e).slice(0,300)); process.exit(1); });
